<?php
require_once __DIR__ . '/_layout.php';requirePermission('invoices.manage');$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$invoices=dbFetchAll("SELECT i.*,c.first_name,c.last_name,c.company_name,r.reference FROM invoices i JOIN customers c ON c.id=i.customer_id LEFT JOIN reservations r ON r.id=i.reservation_id WHERE i.agency_id IN ($ph) ORDER BY i.issued_at DESC",$ids);backofficeHeader('Invoices','invoices.php');?><div class="page-head"><h1>Invoice register</h1></div><div class="table-wrap"><table><tr><th>Number</th><th>Customer</th><th>Reservation</th><th>Issued</th><th>Total</th><th>Paid</th><th>Status</th><th>Document</th></tr><?php foreach($invoices as $i):?><tr><td><?=e($i['invoice_number'])?></td><td><?=e($i['company_name']?:$i['first_name'].' '.$i['last_name'])?></td><td><?=e($i['reference'])?></td><td><?=e($i['issued_at'])?></td><td><?=money($i['total_amount'],$i['currency'])?></td><td><?=money($i['paid_amount'],$i['currency'])?></td><td><?=statusBadge($i['status'])?></td><td><a class="btn secondary" target="_blank" href="invoice_print.php?id=<?=e($i['id'])?>">Print / PDF</a></td></tr><?php endforeach;?></table></div><?php backofficeFooter();
